package com.bysellens.product;
import java.nio.file.*;import java.io.*;import java.util.*;import javax.imageio.ImageIO;import org.springframework.stereotype.Component;import org.springframework.beans.factory.annotation.Value;import org.springframework.web.multipart.MultipartFile;import org.springframework.core.io.*;import com.bysellens.common.DomainException;
@Component public class Images {
 private final Path directory;
 public Images(@Value("${UPLOAD_DIR:./uploads/productos}")String dir)throws IOException{directory=Path.of(dir).toAbsolutePath().normalize();Files.createDirectories(directory);}
 public String save(MultipartFile file){if(file==null||file.isEmpty())return null;if(file.getSize()>5*1024*1024)throw new DomainException(400,"Imagen demasiado grande");try{byte[] bytes=file.getBytes();String ext;if(bytes.length>8&&bytes[0]==(byte)0x89&&bytes[1]==0x50&&bytes[2]==0x4e&&bytes[3]==0x47)ext="png";else if(bytes.length>3&&bytes[0]==(byte)0xff&&bytes[1]==(byte)0xd8&&bytes[2]==(byte)0xff)ext="jpg";else throw new DomainException(400,"Solo PNG o JPEG");try(var input=ImageIO.createImageInputStream(new ByteArrayInputStream(bytes))){var readers=ImageIO.getImageReaders(input);if(!readers.hasNext())throw new DomainException(400,"Imagen invalida");var reader=readers.next();try{reader.setInput(input);long pixels=(long)reader.getWidth(0)*reader.getHeight(0);if(pixels>20_000_000)throw new DomainException(400,"Dimensiones excesivas");var image=reader.read(0);String name=UUID.randomUUID()+"."+ext;ImageIO.write(image,ext,directory.resolve(name).toFile());return name;}finally{reader.dispose();}}}catch(IOException e){throw new DomainException(400,"No se pudo validar la imagen");}}
 public Resource get(String name){if(!name.matches("[a-f0-9-]{36}[.](png|jpg)"))throw DomainException.missing();Path file=directory.resolve(name).normalize();if(!file.startsWith(directory)||!Files.isRegularFile(file))throw DomainException.missing();return new FileSystemResource(file);}
}